// electron-builder config for Moneo Desktop (npm run desktop:dist, after npm run desktop:build).
// desktop/ is the app: only dist/, setup/ and the icon go into app.asar; the Next server, migrations
// and native backend are extraResources next to it. Unsigned unless signing credentials are in the
// environment (CSC_LINK + CSC_KEY_PASSWORD; on macOS also APPLE_ID, APPLE_APP_SPECIFIC_PASSWORD and
// APPLE_TEAM_ID for notarization).
const signed = Boolean(process.env.CSC_LINK);
const notarize = Boolean(process.env.APPLE_ID && process.env.APPLE_APP_SPECIFIC_PASSWORD && process.env.APPLE_TEAM_ID);

/** @type {import("electron-builder").Configuration} */
module.exports = {
  appId: "app.moneo.desktop",
  productName: "Moneo",
  copyright: "Copyright © 2026 Moneo contributors",
  electronVersion: require("../node_modules/electron/package.json").version,
  directories: { output: "release", buildResources: "icons" },
  files: ["package.json", "dist/**", "setup/**", "icons/icon.png"],
  asar: true,
  // desktop/package.json has no dependencies: everything the main process needs is bundled by esbuild.
  npmRebuild: false,
  nodeGypRebuild: false,
  // One entry from .build: electron-builder always drops the node_modules directly inside a `from`
  // folder, and the Next server and Storage API need theirs (here one level down).
  extraResources: [{
    from: ".build",
    to: ".",
    filter: ["app/**/*", "migrations/**/*", "bootstrap/**/*", "backend/${os}-${arch}/**/*", "storage-api/**/*"],
  }],
  electronFuses: {
    runAsNode: false,
    enableNodeOptionsEnvironmentVariable: false,
    enableNodeCliInspectArguments: false,
    enableCookieEncryption: true,
    onlyLoadAppFromAsar: true,
    enableEmbeddedAsarIntegrityValidation: true,
  },
  win: {
    target: [{ target: "nsis", arch: ["x64"] }],
    icon: "icons/icon.png",
    executableName: "Moneo",
  },
  nsis: {
    oneClick: true,
    perMachine: false,
    deleteAppDataOnUninstall: false,
    artifactName: "Moneo-Setup-${version}-${arch}.${ext}",
  },
  mac: {
    target: [{ target: "dmg", arch: ["arm64", "x64"] }, { target: "zip", arch: ["arm64", "x64"] }],
    category: "public.app-category.finance",
    icon: "icons/icon.png",
    hardenedRuntime: true,
    entitlements: "electron-builder.entitlements.mac.plist",
    entitlementsInherit: "electron-builder.entitlements.mac.plist",
    // Ad-hoc signature without credentials (Apple Silicon refuses to run unsigned code).
    identity: signed ? undefined : "-",
    notarize: signed && notarize,
    extendInfo: { NSMicrophoneUsageDescription: "Moneo uses the microphone for voice conversations about your money." },
  },
  dmg: { artifactName: "Moneo-${version}-${arch}.${ext}" },
  linux: {
    target: [{ target: "AppImage", arch: ["x64"] }, { target: "deb", arch: ["x64"] }],
    category: "Office;Finance",
    icon: "icons/icon.png",
    executableName: "moneo",
    maintainer: "Moneo contributors",
    synopsis: "Personal finance that runs on your own computer",
  },
};
// Downloads, verifies and builds the native backend that Moneo Desktop bundles instead of Docker:
// PostgreSQL 17 with contrib, PostgREST, GoTrue (supabase/auth, cross-compiled with CGO off),
// mkcert and the Storage API (supabase/storage, a Node app). Every download is pinned by
// SHA-256 below; downloads are cached in desktop/.cache, results land in desktop/.build:
//   desktop/.build/backend/<platform>/{postgres/,postgrest/,gotrue/,mkcert[.exe],fs-xattr/,manifest.json}
//   desktop/.build/storage-api/            (platform-independent; see fs-xattr below)
//   desktop/.build/migrations/, desktop/.build/bootstrap/   (copies of supabase/migrations, desktop/bootstrap)
//
//   node scripts/desktop/fetch-backend.mjs --platform win-x64 [--platform mac-arm64 ...] [--skip storage,gotrue]
//
// Platforms: win-x64, mac-arm64, mac-x64, linux-x64. Everything cross-builds from any host except
// the fs-xattr addon for macOS/Linux, which compiles only on a host of that platform (CI does that).
import { createHash } from "node:crypto";
import { spawnSync } from "node:child_process";
import { createReadStream, createWriteStream, existsSync } from "node:fs";
import fs from "node:fs/promises";
import { dirname, join, resolve } from "node:path";
import { Readable } from "node:stream";
import { pipeline } from "node:stream/promises";

const root = resolve(import.meta.dirname, "..", "..");
const cache = join(root, "desktop", ".cache");
const out = join(root, "desktop", ".build");

const PLATFORMS = {
  "win-x64": { os: "win32", arch: "x64", goos: "windows", goarch: "amd64", exe: ".exe", postgres: "x86_64-pc-windows-msvc", postgrest: "windows-x86-64.zip", mkcert: "windows-amd64.exe" },
  "mac-arm64": { os: "darwin", arch: "arm64", goos: "darwin", goarch: "arm64", exe: "", postgres: "aarch64-apple-darwin", postgrest: "macos-aarch64.tar.xz", mkcert: "darwin-arm64" },
  "mac-x64": { os: "darwin", arch: "x64", goos: "darwin", goarch: "amd64", exe: "", postgres: "x86_64-apple-darwin", postgrest: "macos-x86-64.tar.xz", mkcert: "darwin-amd64" },
  "linux-x64": { os: "linux", arch: "x64", goos: "linux", goarch: "amd64", exe: "", postgres: "x86_64-unknown-linux-gnu", postgrest: "linux-static-x86-64.tar.xz", mkcert: "linux-amd64" },
};

// Pinned inputs. To upgrade one, change its version and every sha256 next to it.
export const PINS = {
  // Relocatable builds from PostgreSQL source with all client tools and contrib (pgcrypto, pg_trgm),
  // PostgreSQL License, with bundled dependency notices. zonky's embedded binaries lack pg_dump/pg_restore.
  postgres: {
    version: "17.11", release: "17.11.1", license: "PostgreSQL",
    url: target => `https://github.com/theseus-rs/postgresql-binaries/releases/download/17.11.1/postgresql-17.11.1-${target}.tar.gz`,
    sha256: {
      "win-x64": "9855f1b2a9acf127e148fbdd929ef118bfe2fc095c9358a7da74bdc02cedfc27",
      "mac-arm64": "f4b2ff0587d80b6f22bf09ec2d133a3c2949b6423318d3fed0f4ddddddf2f004",
      "mac-x64": "edb44b25cf8bffec60fa300fbe100fa4238bf2cab4f4bd98d4b7255c61780df3",
      "linux-x64": "aa8e2e97574bd789119ac01f1dddcd7a038c84e5c308d7b753018618258f0fbd",
    },
  },
  postgrest: {
    version: "v16.5", license: "MIT",
    url: asset => `https://github.com/PostgREST/postgrest/releases/download/v16.5/postgrest-v16.5-${asset}`,
    sha256: {
      "win-x64": "17f595b0d8dd37473d0231417dea07c5ac9f791282ff5b017fae51ff29e5de2f",
      "mac-arm64": "d8095cb439de0a3151036df542139e7afca5cebb109ce7f1bae52b3a97e9846a",
      "mac-x64": "dd4d346cd65dba4863ae02686fd09d2e34bbb6889e05d8ff7f1ac42ba0939515",
      "linux-x64": "5099e7ada38f9f6846cd87c14c5f158b7c165f1e9959665ad412e61f4dceba95",
    },
  },
  mkcert: {
    version: "v1.4.4", license: "BSD-3-Clause",
    url: asset => `https://github.com/FiloSottile/mkcert/releases/download/v1.4.4/mkcert-v1.4.4-${asset}`,
    sha256: {
      "win-x64": "d2660b50a9ed59eada480750561c96abc2ed4c9a38c6a24d93e30e0977631398",
      "mac-arm64": "c8af0df44bce04359794dad8ea28d750437411d632748049d08644ffb66a60c6",
      "mac-x64": "a32dfab51f1845d51e810db8e47dcf0e6b51ae3422426514bf5a2b8302e97d4e",
      "linux-x64": "6d31c65b03972c6dc4a14ab429f2928300518b26503f58723e532d1b0a3bbb52",
    },
  },
  // Build-only toolchain for GoTrue, matching supabase/auth's go.mod and Dockerfile.
  go: {
    version: "go1.27.0",
    sha256: {
      "windows-amd64.zip": "f0c0a0d33ba94f4d2c5dbc887334ce678b21813504ddb3aafcb06e60a5a667c4",
      "darwin-arm64.tar.gz": "90493b3bbd5e10f91d12153198bf1994fd756399b4fec93b49b0c6e2acdeeb3e",
      "darwin-amd64.tar.gz": "d3314e25496e4381d71a5c51d2907e7af655d199f6780b549f015bd85fef4986",
      "linux-amd64.tar.gz": "675c26c449cbb18fc24b74650de1eabbae6e16f64326fd85a283fb3b58280685",
      "linux-arm64.tar.gz": "51798d2c42d0e1c6ed7fd9f48728b4193abac9e8aad6dbac2fe96a81f5909bda",
    },
  },
  gotrue: {
    version: "v2.197.0", commit: "4eee58f296d9698a1c2c0ae14d7a0b379c7622d3", license: "MIT",
    url: "https://github.com/supabase/auth/archive/refs/tags/v2.197.0.tar.gz", folder: "auth-2.197.0",
    sha256: "d21291c281604ccc6272c81c6506c8d521bc38d3141b0d339cb1a5988b1d461d",
  },
  storage: {
    version: "v1.88.0", commit: "327681449182ade2f9173c968dd8e8ee3c9888fd", license: "Apache-2.0",
    url: "https://github.com/supabase/storage/archive/refs/tags/v1.88.0.tar.gz", folder: "storage-1.88.0",
    sha256: "09ed5ddb38f44e2bf917b5e5f2a15b243134fa3f5542e9090d2a5ba2c9416731",
  },
};

// PostgreSQL programs the backend uses: server, cluster setup, backups and a shell for support.
const POSTGRES_PROGRAMS = new Set(["postgres", "initdb", "pg_ctl", "pg_dump", "pg_dumpall", "pg_restore", "psql",
  "pg_isready", "pg_controldata", "pg_resetwal", "pg_upgrade", "pg_checksums"]);

function args() {
  const platforms = [], skip = new Set();
  const argv = process.argv.slice(2);
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === "--platform") platforms.push(...argv[++i].split(","));
    else if (argv[i] === "--skip") argv[++i].split(",").forEach(part => skip.add(part));
    else throw new Error(`Unknown argument ${argv[i]}`);
  }
  if (!platforms.length) platforms.push(hostPlatform());
  for (const platform of platforms) if (!PLATFORMS[platform]) throw new Error(`Unknown platform ${platform}; use ${Object.keys(PLATFORMS).join(", ")}`);
  return { platforms, skip };
}

function hostPlatform() {
  const name = Object.entries(PLATFORMS).find(([, p]) => p.os === process.platform && p.arch === process.arch)?.[0];
  if (!name) throw new Error(`No Moneo Desktop backend for ${process.platform}-${process.arch}`);
  return name;
}

function run(command, commandArgs, options = {}) {
  const result = spawnSync(command, commandArgs, { stdio: "inherit", ...options });
  if (result.error) throw result.error;
  if (result.status !== 0) throw new Error(`${command} ${commandArgs.join(" ")} exited with ${result.status}`);
}

async function sha256(file) {
  const hash = createHash("sha256");
  await pipeline(createReadStream(file), hash);
  return hash.digest("hex");
}

async function download(url, expected, name) {
  const file = join(cache, "downloads", name);
  if (existsSync(file) && await sha256(file) === expected) return file;
  await fs.mkdir(dirname(file), { recursive: true });
  console.log(`Downloading ${url}`);
  const response = await fetch(url);
  if (!response.ok) throw new Error(`${url}: HTTP ${response.status}`);
  const partial = `${file}.partial`;
  await pipeline(Readable.fromWeb(response.body), createWriteStream(partial));
  const actual = await sha256(partial);
  if (actual !== expected) { await fs.rm(partial, { force: true }); throw new Error(`${name}: sha256 ${actual}, expected ${expected}`); }
  await fs.rename(partial, file);
  return file;
}

// bsdtar (Windows 10+, macOS) reads zip, gzip and xz; GNU tar on Linux needs unzip for zips.
// On Windows always the system bsdtar, never Git's GNU tar, which reads "C:" as a remote host.

// Smoke test of the PACKAGED desktop app (after npm run desktop:dist). Uses a temporary Moneo home,
// so it never touches the owner's data, and logs external links instead of opening a browser.
//   node scripts/desktop/package-smoke.mjs [path to the executable]
// Playwright drives the app over the Chrome DevTools protocol: the packaged app turns off Node's
// --inspect flag (a security fuse), which Playwright's _electron.launch needs.
import { execFileSync, spawn } from "node:child_process";
import { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { createServer } from "node:net";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { FuseState, FuseV1Options, getCurrentFuseWire } from "@electron/fuses";
import { chromium } from "@playwright/test";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..");
const release = path.join(root, "desktop", "release");
const defaultExe = {
  win32: path.join(release, "win-unpacked", "Moneo.exe"),
  darwin: path.join(release, process.arch === "arm64" ? "mac-arm64" : "mac", "Moneo.app", "Contents", "MacOS", "Moneo"),
  linux: path.join(release, "linux-unpacked", "moneo"),
}[process.platform];
const exe = path.resolve(process.argv[2] ?? defaultExe);
if (!existsSync(exe)) { console.error(`No packaged app at ${exe}. Run npm run desktop:build && npm run desktop:dist first.`); process.exit(1); }

const results = [];
const check = (name, ok, detail = "") => { results.push({ name, ok }); console.log(`${ok ? "PASS" : "FAIL"} ${name}${detail ? ` — ${detail}` : ""}`); };
const until = async (what, test, timeout) => {
  const deadline = Date.now() + timeout;
  for (;;) {
    const value = await test().catch(() => undefined);
    if (value) return value;
    if (Date.now() > deadline) throw new Error(`Timed out waiting for ${what}`);
    await new Promise(resolve => setTimeout(resolve, 250));
  }
};
const freePort = () => new Promise(resolve => { const server = createServer().listen(0, "127.0.0.1", () => { const { port } = server.address(); server.close(() => resolve(port)); }); });
const alive = pid => { try { process.kill(pid, 0); return true; } catch { return false; } };

// Every process started from the app, or naming its home folder (pg_ctl's postgres outlives its parent).
function processesOf(mainPid, home) {
  const rows = process.platform === "win32"
    ? JSON.parse(execFileSync("powershell.exe", ["-NoProfile", "-Command", "Get-CimInstance Win32_Process | Select-Object ProcessId,ParentProcessId,Name,CommandLine | ConvertTo-Json -Compress"], { encoding: "utf8", maxBuffer: 64 << 20 }))
      .map(row => ({ pid: row.ProcessId, ppid: row.ParentProcessId, name: row.Name, command: row.CommandLine ?? "" }))
    : execFileSync("ps", ["-axo", "pid=,ppid=,command="], { encoding: "utf8" }).trim().split("\n").map(line => {
      const [, pid, ppid, command] = line.match(/^\s*(\d+)\s+(\d+)\s+(.*)$/);
      return { pid: Number(pid), ppid: Number(ppid), name: path.basename(command.split(" ")[0]), command };
    });
  const found = new Map(rows.filter(row => row.pid === mainPid || row.command.toLowerCase().includes(home.toLowerCase())).map(row => [row.pid, row]));
  for (let grew = true; grew;) {
    grew = false;
    for (const row of rows) if (found.has(row.ppid) && !found.has(row.pid)) { found.set(row.pid, row); grew = true; }
  }
  return [...found.values()];
}

const user32 = `Add-Type -Namespace W -Name U -MemberDefinition '[DllImport("user32.dll")] public static extern bool PostMessage(IntPtr h, uint m, IntPtr w, IntPtr l); [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr h);'`;
const win32 = command => execFileSync("powershell.exe", ["-NoProfile", "-Command", `${user32}; ${command}`], { encoding: "utf8" }).trim();

const fuses = await getCurrentFuseWire(exe);
const fuseOff = option => fuses[option] === FuseState.DISABLE;
const fuseOn = option => fuses[option] === FuseState.ENABLE;
check("fuses: RunAsNode, NODE_OPTIONS and --inspect off; cookie encryption, asar-only and asar integrity on",
  fuseOff(FuseV1Options.RunAsNode) && fuseOff(FuseV1Options.EnableNodeOptionsEnvironmentVariable) && fuseOff(FuseV1Options.EnableNodeCliInspectArguments)
  && fuseOn(FuseV1Options.EnableCookieEncryption) && fuseOn(FuseV1Options.OnlyLoadAppFromAsar)
  && (process.platform === "linux" || fuseOn(FuseV1Options.EnableEmbeddedAsarIntegrityValidation)));

const home = mkdtempSync(path.join(os.tmpdir(), "moneo-desktop-smoke-"));
const externalLog = path.join(os.tmpdir(), `moneo-desktop-smoke-${process.pid}-external.log`);
writeFileSync(externalLog, "");
const env = { ...process.env, MONEO_DESKTOP_HOME: home, MONEO_DESKTOP_OPEN_EXTERNAL_LOG: externalLog };
const cdpPort = await freePort();
const app = spawn(exe, [`--remote-debugging-port=${cdpPort}`], { env, stdio: "ignore" });
let exited = false;
app.on("exit", () => { exited = true; });
let seen = [];
let browser;

try {
  // The window list over plain HTTP sees each window as soon as it exists.
  const listed = async () => (await (await fetch(`http://127.0.0.1:${cdpPort}/json/list`)).json()).map(target => target.url);
  await until("the setup window", async () => (await listed()).some(url => url.endsWith("/setup/index.html")), 30_000);
  check("setup window appears", true);
  await until("the app window", async () => (await listed()).some(url => /^http:\/\/localhost:\d+\//.test(url)), 240_000);
  browser = await chromium.connectOverCDP(`http://127.0.0.1:${cdpPort}`);
  const context = browser.contexts()[0];
  const appPage = await until("the app page", async () => context.pages().find(page => /^http:\/\/localhost:\d+\//.test(page.url())), 10_000);
  await appPage.waitForLoadState("load");
  const port = Number(new URL(appPage.url()).port);
  const realBackend = existsSync(path.join(home, "config.json"));
  const landed = new URL(appPage.url()).pathname;
  const text = await appPage.locator("body").innerText();
  check(`app window loads ${realBackend ? "Home" : "(stub backend)"}`, realBackend ? landed === "/" && !/could not sign you in/i.test(text) : /Moneo/.test(text), `${appPage.url()} on port ${port}`);
  check("setup window closed after start", !(await listed()).some(url => url.endsWith("/setup/index.html")));

  const external = "https://example.com/moneo-desktop-smoke";
  await appPage.evaluate(url => { window.location.assign(url); }, external);
  await until("the external link in the log", async () => readFileSync(externalLog, "utf8").includes(external), 10_000);
  check("external navigation goes to the system browser, not the window", new URL(appPage.url()).hostname === "localhost");
  const popup = "https://example.org/moneo-desktop-popup";
  await appPage.evaluate(url => { window.open(url, "_blank"); }, popup);
  await until("the popup in the log", async () => readFileSync(externalLog, "utf8").includes(popup), 10_000);
  check("window.open goes to the system browser", context.pages().every(page => !page.url().includes("example.org")));

  seen = processesOf(app.pid, home);
  console.log(`  processes: ${seen.map(row => `${row.name}#${row.pid}`).join(", ")}`);

  // Windows: the message the title bar's close button sends. Elsewhere: the page asks to close.
  if (process.platform === "win32") {
    const handle = win32(`(Get-Process -Id ${app.pid}).MainWindowHandle`);
    win32(`[W.U]::PostMessage([IntPtr]${handle}, 0x10, [IntPtr]::Zero, [IntPtr]::Zero)`);
    await until("the window to hide", async () => win32(`[W.U]::IsWindowVisible([IntPtr]${handle})`) === "False", 10_000);
  } else {
    await appPage.evaluate(() => window.close());
    await until("the window to hide", async () => await appPage.evaluate(() => document.visibilityState) === "hidden", 10_000);
  }
  const health = await fetch(`http://127.0.0.1:${port}/api/health`, { headers: { authorization: "Bearer smoke" } });
  check("closing the window hides it and the server keeps answering", !exited && health.ok, `health ${health.status}`);

  // Explicit quit, as a second launch with --quit (what the tray's Quit does in-process).
  spawn(exe, ["--quit"], { env, stdio: "ignore" });
